  + Name : string
}

class Teacher {
  + Name : string
}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

class MasterStudent {
}

class ExternalAuditor {
}

MasterCourse "1" -- "0..*" CourseEdition
CourseEdition "1" *-- "1..*" Lesson
Lesson "1" -- "0..*" AdditionalResource
Lesson "1..*" -- "1..*" Teacher
MasterCourse "0..*" -- "0..*" Teacher

CourseEdition "1" -- "1" InternalTeacher : responsible
CourseEdition "1" -- "0..*" MasterStudent
CourseEdition "1" -- "0..*" ExternalAuditor

@enduml

